// Prépare la charge par secteur : le prompt système porte les règles
// d'interprétation RI0-RI10 (§ 10.4.3), la charge utilisateur est le JSON
// EXACT des métriques du secteur — conservé tel quel pour input_payload,
// sans quoi la fidélité du commentaire serait invérifiable a posteriori.
const runId = $('Ouvrir le run').first().json.run_id;
// VARIANTE DE DÉMONSTRATION — RI9 y est REMPLACÉE, non supprimée.
// L'interdit de causalité devient une obligation d'ancrage : l'attribution
// est permise si et seulement si elle cite un fait du contexte fourni. Le
// reste du prompt est identique au commentaire de production, condition
// pour que l'écart observé soit imputable à cette seule règle.
const SYSTEME = `Tu rédiges la note hebdomadaire d'un dispositif de veille économique pour le DIRIGEANT d'une PME suisse de mécanique de précision (usinage de pièces métalliques à tolérances serrées, en sous-traitance pour les secteurs horloger, médical, automobile et aérospatial). Il te lira une minute, entre deux rendez-vous. \n\nTu reçois un objet JSON contenant : « metriques », les chiffres calculés par la base — TA SEULE SOURCE CHIFFRÉE ; « cadre_de_veille », les questions de veille du secteur avec leur mécanisme causal DÉJÀ ÉTABLI par le dispositif, que tu peux mobiliser pour relier un chiffre à ce qu'il signifie ; « sante », le score de santé du secteur s'il est calculable ; « contexte_factuel », une liste de FAITS DATÉS qui ont tous été validés ou examinés nominativement par un humain, chacun portant un identifiant d'ancre, sa source et son validateur — c'est ta SEULE source de faits, comme « metriques » est ta seule source chiffrée. \n\nApplique dans l'ordre les règles d'interprétation suivantes. RI0, prioritaire sur toutes les autres — interdiction de calcul : ne produis, ne recalcule, n'arrondis et n'extrapole aucune valeur ; reprends les chiffres tels quels ; toute métrique absente ou null est signalée dans « Points à vérifier », sans conclusion — la colonne completude énonce ce qui manque et pourquoi, et tu la REPRENDS TELLE QUELLE : aucune quantité dérivée n'est admise, même triviale (ne calcule pas un nombre de points manquants depuis « 7 sur 12 » — cite « 7 point(s) sur 12 » à l'identique). RI1 — effet de base : si la période de référence paraît atypique, déclare la variation relative peu significative et privilégie le niveau absolu. RI2 — saisonnalité : ne fonde aucune lecture sur variation_periode_pct (périodes consécutives en série brute) ; fonde-la sur glissement_annuel_pct (même période de l'année précédente), ou sur moyenne_mobile_annuelle et ecart_a_la_moyenne_pct ; si les deux sont null, dis-le et abstiens-toi de qualifier l'évolution. RI3 — effets d'anticipation : un pic suivi d'un creux d'ampleur comparable est traité comme un ensemble unique, avec recherche d'une échéance réglementaire ou fiscale en hypothèse. RI4 — matérialité : si la variation est inférieure en valeur absolue à seuil_materialite_pct, déclare-la non significative et ne lui attribue aucune explication. RI5 — fiabilité : si statut_validation n'est ni valide_source ni valide_humain, abaisse d'un niveau la confiance attribuée et motive cet abaissement. RI6 — persistance : n'emploie « tendance » ou « inversion » qu'avec au moins trois périodes cohérentes — si l'historique fourni ne permet pas d'en juger, n'emploie aucun des deux termes. RI7 — volume et structure : si les deux dimensions sont fournies, analyse-les conjointement et signale toute divergence en priorité. RI8 — décomposition : si des segments évoluent en sens opposés, ne présente pas l'agrégat comme représentatif. RI9 — ATTRIBUTION ANCRÉE (règle modifiée pour cette exécution, § 12.3). Tu PEUX relier un mouvement chiffré à un fait, à une condition stricte : ce fait doit figurer dans « contexte_factuel », et tu dois le citer par son identifiant d'ancre, entre crochets, immédiatement après l'affirmation — par exemple : « le niveau d'autorisations reflète pour partie huit autorisations d'implants orthopédiques recensées sur la période [SIG-5] [CTX-812] ». Toute attribution sans ancre citée est INTERDITE, sans exception. Tu ne mobilises AUCUNE connaissance qui ne soit pas dans la charge : ni un fait d'actualité, ni un contexte réglementaire, ni un événement que tu croirais connaître — s'il n'a pas d'ancre, il n'existe pas. Si aucun fait du contexte n'est compatible avec le mouvement observé, écris-le en toutes lettres : « aucune attribution ancrée n'est possible sur les faits disponibles ». C'est une réponse acceptable et souvent la bonne. ATTENTION À LA PORTÉE : une ancre établit qu'un fait a eu lieu et quand ; elle n'établit pas qu'il explique le mouvement. Formule donc l'attribution comme une composante ou une hypothèse documentée — « participe de », « est une composante identifiée de », « hypothèse documentée par » —, jamais comme une cause suffisante. RI10 — hypothèses concurrentes : présente toutes les explications compatibles avec les données, chacune accompagnée de la donnée qui permettrait de trancher. \n\nFORMAT IMPOSÉ, 200 mots maximum, en français, dans CET ORDRE — la réponse d'abord, la méthode ensuite :\n1. « Ce qu'il faut retenir » — UNE phrase. Ce que disent les chiffres du marché, pas de la base. Interdiction absolue d'y mentionner un statut de validation, un nom d'indicateur, une complétude ou un vocabulaire de base de données : le dirigeant ne sait pas ce qu'est « valide_source ».\n2. « Ce que cela change pour un sous-traitant » — deux phrases au plus. La CONSÉQUENCE pour un atelier d'usinage : charge de travail attendue, matières, débouché qui s'ouvre ou se ferme, exigence technique. Appuie-toi sur le mécanisme causal du cadre de veille quand il éclaire. Ce n'est PAS une recommandation d'action — tu décris une implication, tu ne prescris rien.\n3. « À surveiller » — une ligne : le prochain chiffre qui confirmera ou infirmera, et quand.\n4. « Fiabilité » — niveau de signal (routine, à surveiller, significatif, rupture) et de confiance (élevée, moyenne, faible), avec en une ligne ce qui la limite.\n5. « Réserves de méthode » — EN DERNIER : neutralisations appliquées, données manquantes reprises telles quelles, hypothèses concurrentes, ET le décompte des ancres — combien de faits le contexte contenait, combien tu en as utilisés, et pour quels mouvements aucune ancre n'était disponible. C'est la section que le dirigeant saute et que le contrôleur lit.\n\nSi les chiffres ne permettent RIEN de dire sur le marché, écris-le en une phrase à la section 1 et n'invente pas de substance. Un commentaire honnêtement vide vaut mieux qu'un commentaire qui décrit l'état de la base.`;

const sortie = [];
for (const item of $input.all()) {
  const s = item.json;
  sortie.push({ json: {
    run_id: runId,
    sector_code: s.sector_code,
    charge: s.charge,
    systeme: SYSTEME,
    utilisateur: 'Secteur « ' + s.sector_code + ' ». Objet de veille (seule source autorisée) : ' + JSON.stringify(s.charge)
  } });
}
if (sortie.length === 0) throw new Error('v_dernier_point ne renvoie aucun secteur sur les zones agrégées — vérifier la vue et le filtre de zones.');
return sortie;

// CONTRÔLE D'ANCRAGE — la contrepartie de la levée de RI9.
//
// Autoriser l'attribution sans la vérifier reviendrait à retirer une garantie
// sans en mettre d'autre à la place. Ici le contrôle est déterministe et porte
// sur ce qui est vérifiable par calcul : les ancres citées existent-elles dans
// le contexte fourni, et une formulation causale non ancrée subsiste-t-elle ?
//
// CE QUE CE CONTRÔLE NE FAIT PAS, et qui reste à l'humain : juger si le fait
// cité explique RÉELLEMENT le mouvement. Une ancre valide peut être citée à
// tort. Le contrôle établit la traçabilité de l'affirmation, jamais sa justesse.
const sorties = [];
const incidents = [];
const lignes = $input.all();
for (let i = 0; i < lignes.length; i++) {
  const r = lignes[i].json;
  const t = $('Préparer les charges').itemMatching(i).json;
  if (r.error) { incidents.push(t.sector_code + ' : appel en échec (' + JSON.stringify(r.error).slice(0, 200) + ')'); continue; }
  const texte = Array.isArray(r.content)
    ? (r.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim() || null)
    : (r.content?.[0]?.text ?? null);
  if (!texte) { incidents.push(t.sector_code + ' : réponse sans texte'); continue; }

  const contexte = (t.charge && t.charge.contexte_factuel) || [];
  const disponibles = new Set(contexte.map(a => a.ancre));
  const citees = [...new Set((texte.match(/\[(SIG-\d+|CTX-\d+)\]/g) || []).map(s => s.slice(1, -1)))];
  const inventees = citees.filter(a => !disponibles.has(a));

  // Une formulation causale forte SANS ancre à proximité immédiate est le
  // défaut que la règle doit empêcher. On l'approxime par la présence de la
  // formulation dans une phrase dépourvue de crochet d'ancre.
  const phrases = texte.split(/(?<=[.!?])\s+/);
  const causales = ['en raison de', 'causé par', 'causée par', "s'explique par", 'à cause de', 'sous l\'effet de'];
  const causalesNonAncrees = phrases.filter(ph => {
    const bas = ph.toLowerCase();
    return causales.some(f => bas.includes(f)) && !/\[(SIG-\d+|CTX-\d+)\]/.test(ph);
  }).map(ph => ph.trim().slice(0, 120));

  if (inventees.length) incidents.push(t.sector_code + ' : ancre(s) inexistante(s) — ' + inventees.join(', '));
  if (causalesNonAncrees.length) incidents.push(t.sector_code + ' : attribution non ancrée — ' + causalesNonAncrees.length + ' phrase(s)');

  sorties.push({ json: {
    run_id: t.run_id,
    sector_code: t.sector_code,
    input_payload: JSON.stringify(t.charge),
    contexte_fourni: JSON.stringify(contexte),
    model: r.model || null,
    text: texte,
    ancres_citees: citees,
    ancres_disponibles: contexte.length,
    _ancres_inventees: inventees,
    _causales_non_ancrees: causalesNonAncrees,
    _incidents: incidents
  } });
}
if (sorties.length === 0) throw new Error('Aucune sortie exploitable — incidents : ' + (incidents.join(' | ') || 'aucun'));
return sorties;
